inputs.code:
// Normalise the caller's inputs, and mint the run id.
//
// AN OMITTED INPUT IS AN UNBOUND VARIABLE, NOT A NULL. When a caller leaves `dryRun`
// out entirely, the START node has no such output, the parameter's expression resolves
// to nothing, and the script does not receive the variable at all - referencing it dies
// with `No such property: dryRun for class: Script_<hash>`. `?:` cannot save a name
// that was never bound, so every optional input is read through `binding.hasVariable`.
//
// This is the second half of the shared contract's input rule. That rule says real
// callers send EMPTY STRINGS for what they did not fill; they also sometimes send
// nothing at all, and the two fail in completely different places.
//
// An unusable periodId becomes a SENTINEL rather than an empty filter. The fetch
// downstream then keeps one property and one operator whatever the caller sent, which
// is what lets the builder draw its filter and the index analyser read it - an empty
// or absent filter would silently fetch every Period instead of none.

def opt = { String name -> binding.hasVariable(name) ? binding.getVariable(name) : null }

String pid = opt('periodId') == null ? '' : String.valueOf(opt('periodId')).trim()
boolean inputOk = !pid.isEmpty()

// "" is missing, not false. A caller that omits dryRun gets the SAFE answer: compute
// and report, write nothing. Writing pay is opt-in, never the default.
String dr = opt('dryRun') == null ? '' : String.valueOf(opt('dryRun')).trim().toLowerCase()
boolean dry = dr.isEmpty() ? true : (dr == 'true')

int limit = 1000
String pl = opt('pageLimit') == null ? '' : String.valueOf(opt('pageLimit')).trim()
if (!pl.isEmpty()) {
    try { limit = Integer.parseInt(pl) } catch (Exception e) { limit = 1000 }
}
if (limit < 1) limit = 1
if (limit > 5000) limit = 5000

// How many distinct keys one staged read's IN filter may carry. The reads are keyed on
// the previous stage's output, so this is the bound on the JOIN rather than on the page:
// a period touching more distinct payees than this needs calculating in chunks, and the
// fold refuses with KEY_SET_TOO_LARGE rather than sending a filter nobody sized.
int cap = 5000
String kc = opt('keyCap') == null ? '' : String.valueOf(opt('keyCap')).trim()
if (!kc.isEmpty()) {
    try { cap = Integer.parseInt(kc) } catch (Exception e) { cap = 5000 }
}
if (cap < 1) cap = 1
if (cap > 20000) cap = 20000

// The engine mints the run id; the caller cannot supply one. That is what makes the
// UNIQUE key on CalculationRun.runId un-hittable without a pre-check fetch, and the
// reason there is no pre-check node in this flow.
long now = System.currentTimeMillis()
String runId = 'RUN-' + now + '-' + Long.toHexString(new Random(now).nextInt(0x1000000))

return [
    periodId : inputOk ? pid : '__invalid_input__',
    inputOk  : inputOk,
    dryRun   : dry,
    pageLimit: limit,
    keyCap   : cap,
    runId    : runId,
    startedAt: now,
]

// Decide whether this period may be calculated at all, and hand the window down.
//
// Three refusals, each with its own caller-actionable status, because "it did not run"
// is not an answer anybody can act on:
//
//   INVALID_INPUT     the caller sent no periodId
//   PERIOD_NOT_FOUND  they sent one no Period carries
//   PERIOD_NOT_OPEN   the period is CLOSED, PAID or already CALCULATING
//
// CLOSED and PAID are the audit boundary — recalculating a paid month is how a number
// somebody has already been paid against silently changes. CALCULATING means another
// run holds it.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

List periods = rows(periodRows)

if (!(inputOk instanceof Boolean ? inputOk : String.valueOf(inputOk) == 'true')) {
    return [ok: false, status: 'INVALID_INPUT', message: 'periodId is required']
}
if (periods.isEmpty()) {
    return [ok: false, status: 'PERIOD_NOT_FOUND', message: "no Period with id ${periodId}".toString()]
}

def period = periods[0]
String st = String.valueOf(p(period, 'status'))
if (st != 'OPEN') {
    return [ok: false, status: 'PERIOD_NOT_OPEN',
            message: "period ${p(period, 'name')} is ${st}; only an OPEN period may be calculated".toString()]
}

def s = p(period, 'startDate'), e = p(period, 'endDate')
if (s == null || e == null) {
    return [ok: false, status: 'PERIOD_NOT_USABLE',
            message: "period ${p(period, 'name')} has no start or end date".toString()]
}

return [
    ok         : true,
    status     : 'OK',
    message    : '',
    periodName : String.valueOf(p(period, 'name')),
    windowStart: ((Number) s).longValue(),
    windowEnd  : ((Number) e).longValue(),
]

// Which credit run to pay from, and which payout runs this one will supersede.
//
// The credit run is the period's LATEST Succeeded, non-dry run whose scope is not a payout
// run. Calculate Credits writes `scope: {}`; this automation writes `scope.stage = "payout"`.
// Older credit runs are not marked Superseded by anything today, so "latest by startedAt"
// is the rule, stated in the spec.
//
// A TRUNCATED run read is refused here, before anything else. Every wet payout run adds a
// Succeeded run to the period, so a page that did not hold them all can hide the credit run
// and answer NO_CREDIT_RUN for a period that was credited (caught by the suite, 2026-09-11).

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }
def truthy(v) { return v instanceof Boolean ? v : String.valueOf(v) == 'true' }
def opt = { String n -> binding.hasVariable(n) ? binding.getVariable(n) : null }

if (truthy(opt('runMore'))) {
    return [found: false, status: 'FETCH_TRUNCATED',
            message: 'this period has more finished runs than one page held, so the credit run cannot be picked safely. Raise pageLimit.',
            creditRunId: '__none__', creditRunKey: '', payoutRunIds: ['__none__']]
}

String creditRun = null
String creditRunKey = ''
long best = Long.MIN_VALUE
Set payoutRuns = new LinkedHashSet()

for (r in rows(runRows)) {
    if (p(r, 'status') != 'Succeeded') continue
    if (truthy(p(r, 'dryRun'))) continue
    def scope = p(r, 'scope')
    def stage = (scope instanceof Map) ? scope.stage : null
    if (stage == 'payout') { payoutRuns << String.valueOf(r.id); continue }
    if (stage != null && stage != 'credit') continue
    def started = p(r, 'startedAt')
    long s = started instanceof Number ? ((Number) started).longValue() : 0L
    if (creditRun == null || s > best) {
        creditRun = String.valueOf(r.id)
        creditRunKey = String.valueOf(p(r, 'runId'))
        best = s
    }
}

boolean found = creditRun != null
return [
    found       : found,
    status      : found ? 'OK' : 'NO_CREDIT_RUN',
    message     : found ? '' : 'this period has no Succeeded, non-dry-run credit run; run ICM | Calculate Credits with dryRun false first',
    creditRunId : creditRun ?: '__none__',
    creditRunKey: creditRunKey,
    payoutRunIds: payoutRuns.isEmpty() ? ['__none__'] : new ArrayList(payoutRuns),
]

// The keys every later read is filtered by: the credits' transactions, seats and types.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }
def nn = { Set s -> s.isEmpty() ? ['__none__'] : new ArrayList(s) }

int cap = ((Number) keyCap).intValue()
Set txns = new LinkedHashSet(), seats = new LinkedHashSet(), types = new LinkedHashSet()
for (r in rows(creditRows)) {
    def t = p(r, 'transactionId'); if (t != null) txns << String.valueOf(t)
    def s = p(r, 'positionId');    if (s != null) seats << String.valueOf(s)
    def c = p(r, 'creditTypeId');  if (c != null) types << String.valueOf(c)
}
return [transactionIds: nn(txns), positionIds: nn(seats), creditTypeIds: nn(types),
        count: rows(creditRows).size(),
        overflow: txns.size() > cap || seats.size() > cap]

// Stage 4 -> 5: the TITLE ids those seats carried in the window.
//
// Titles are fetched by id rather than whole because the title CODE is load-bearing - a
// rule stores `position.title == "T-AE"` and the seat stores a record id - so the wrong
// or missing code produces a rule that matches nothing and says nothing.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

Set titles = new LinkedHashSet()
Set terrs = new LinkedHashSet()
for (r in rows(attrRows)) {
    def t = p(r, 'titleId'); if (t != null) titles << String.valueOf(t)
    def y = p(r, 'territoryId'); if (y != null) terrs << String.valueOf(y)
}
return [titleIds: titles.isEmpty() ? ['__none__'] : new ArrayList(titles),
        territoryIds: terrs.isEmpty() ? ['__none__'] : new ArrayList(terrs),
        count: titles.size()]

// Stage 5 -> 6: every key a PlanAssignment might name this seat or title by.
//
// The live data names targets FOUR ways: a record id in `targetId`, a record id in
// `positionId`/`titleId`, and a business CODE in either. PLAN-1789032727380-3055 stores
// the string "POS-UK-AE-02" in a column typed as a foreign key to Position. So the key
// set is ids AND codes, and the fold accepts both.
//
// ONE FETCH, NOT THREE. The read is a STRUCTURED top-level OR -
// `targetId IN all OR positionId IN seats OR titleId IN titles` - which the builder draws
// and the index analyser reads, unlike a Groovy-built pill. The `startDate <= windowEnd`
// trim is dropped to keep it one flat OR: a seat has a handful of assignments over its
// life, and the fold judges every one of them by date anyway.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

Set posKeys = new LinkedHashSet()
for (v in rows(positionIds)) if (v != null && v != '__none__') posKeys << String.valueOf(v)
for (r in rows(posRows)) { def c = p(r, 'positionCode'); if (c != null) posKeys << String.valueOf(c) }

Set titleKeys = new LinkedHashSet()
for (v in rows(titleIds)) if (v != null && v != '__none__') titleKeys << String.valueOf(v)
for (r in rows(titleRows)) { def c = p(r, 'titleCode'); if (c != null) titleKeys << String.valueOf(c) }

Set all = new LinkedHashSet(); all.addAll(posKeys); all.addAll(titleKeys)
def nn = { Set s -> s.isEmpty() ? ['__none__'] : new ArrayList(s) }
return [positionKeys: nn(posKeys), titleKeys: nn(titleKeys), allKeys: nn(all), count: all.size()]

// Stage 6 -> 7: the plans those assignments point at.
//
// Status is NOT filtered here. A plan that is Draft or out of force still has to come
// back, because "an assignment points at a plan that is not usable" and "no assignment
// exists at all" are different answers to the rep, and filtering by status would collapse
// them into the second one.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

Set ids = new LinkedHashSet()
for (r in rows(asgRows)) { def v = p(r, 'planId'); if (v != null) ids << String.valueOf(v) }
return [planIds: ids.isEmpty() ? ['__none__'] : new ArrayList(ids), count: ids.size()]

// The payout rules those plans list. `Plan.payoutRules` holds BUSINESS keys, so the Rule
// fetch filters on properties.ruleId. A key no Rule carries is reported by the fold as
// RULE_MISSING against the credits it would have paid.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

Set keys = new LinkedHashSet()
for (r in rows(planRows)) {
    def list = p(r, 'payoutRules')
    Collection parts = list instanceof Collection ? (Collection) list : (list == null ? [] : String.valueOf(list).split(',') as List)
    for (k in parts) if (k != null && !String.valueOf(k).trim().isEmpty()) keys << String.valueOf(k).trim()
}
return [ruleIds: keys.isEmpty() ? ['__none__'] : new ArrayList(keys), count: keys.size()]

// Does any rule need the tiered reads, and which rows exactly.
//
// A period whose plans only pay flat rates never reads a measure, a quota or a rate table:
// the branch lane in front of those reads stays closed.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }
def nn = { Set s -> s.isEmpty() ? ['__none__'] : new ArrayList(s) }

Set measures = new LinkedHashSet(), tables = new LinkedHashSet(), quotas = new LinkedHashSet()
for (r in rows(ruleRows)) {
    if (p(r, 'stage') != 'payout') continue
    Map values = (Map) (((Map) p(r, 'result'))?.values ?: [:])
    if (String.valueOf(values.rateType).trim() != 'Tiered') continue
    def m = values.measureId;   if (m != null && !String.valueOf(m).trim().isEmpty()) measures << String.valueOf(m).trim()
    def t = values.rateTableId; if (t != null && !String.valueOf(t).trim().isEmpty()) tables << String.valueOf(t).trim()
    def q = values.quotaId;     if (q != null && !String.valueOf(q).trim().isEmpty()) quotas << String.valueOf(q).trim()
}
return [measureIds: nn(measures), rateTableIds: nn(tables), quotaIds: nn(quotas),
        readTiered: !measures.isEmpty() || !tables.isEmpty()]

// RateTableBand.rateTableId is a foreign key to the RateTable RECORD, while a rule names
// the table by its business key - so the bands are read by the record ids found here.

def rows(v) { return (v instanceof List) ? v : [] }

Set ids = new LinkedHashSet()
for (r in rows(rtRows)) if (r?.id != null) ids << String.valueOf(r.id)
return [rateTableRecordIds: ids.isEmpty() ? ['__none__'] : new ArrayList(ids), count: ids.size()]

// ICM | Condition Matcher
//
// The calculation engine's rule-resolution core. Decides whether one Rule's
// `conditions` apply to one row of facts. PURE: no I/O, no platform calls, no
// clock, no randomness — which is what lets it be proved against a case table
// in a single code node instead of only against a seeded environment.
//
// Spec, and the reasoning behind every edge: engine/condition-grammar.md
// Authoring dual:  app/src/components/plan/condition-namespace.ts
// The two are bound by engine/condition-namespace.test.ts — edit one and that test fails.
//
// This file is the SOURCE OF TRUTH. The platform copy lives in a code node; when
// they disagree, this is right and the node is stale.

import java.math.BigDecimal

class ConditionMatcher {

    /** The complete operator set. Anything else is reported, never evaluated. */
    static final List OPERATORS = ['==', '!=', '>', '>=', '<', '<=', 'in']

    /**
     * Subject -> kind, mirrored from condition-namespace.ts. A subject that is not
     * here cannot be evaluated: it would read as nothing and match nothing, which
     * is the silent failure this map exists to turn into a reported one.
     *
     * `txn.attrs.<key>` is the one open-ended subject (the form types the key
     * beside the picker), so it is matched by prefix rather than listed.
     */
    static final Map KINDS = [
        // credit stage — reads the incoming deal, the seat, the person
        'txn.amount'         : 'number',
        'txn.product'        : 'string',
        'txn.customer'       : 'string',
        'txn.close_date'     : 'date',
        // payout stage — reads what the credit stage produced
        'credit.amount'      : 'number',
        'credit.credit_type' : 'string',
        'credit.close_date'  : 'date',
        'credit.is_rollup'   : 'boolean',
        'credit.product'     : 'string',
        'credit.customer'    : 'string',
        'attainment.pct'     : 'number',
        'attainment.measure' : 'string',
        'period.type'        : 'enum',
        // both stages
        'position.title'     : 'string',
        'position.territory' : 'string',
        'payee.currency'     : 'string',
        'payee.hire_date'    : 'date',
    ]

    static String kindOf(String subject) {
        if (subject == null) return null
        if (KINDS.containsKey(subject)) return KINDS[subject]
        if (subject.startsWith('txn.attrs.') && subject.length() > 'txn.attrs.'.length()) return 'string'
        return null
    }

    /** Which operators are meaningful on a kind. `>` on a boolean is not a filter anyone meant. */
    static List operatorsFor(String kind) {
        if (kind == 'number' || kind == 'date') return ['==', '!=', '>', '>=', '<', '<=']
        if (kind == 'boolean') return ['==', '!=']
        return ['==', '!=', 'in']
    }

    /**
     * Money and any other number. Never Double: a storage `number` comes back as
     * BigDecimal below 10^7 and Double at or above it, and Groovy promotes
     * BigDecimal + Double to Double — so one large row silently poisons the rest.
     * See ua-icm docs/model/money-and-time.md.
     */
    static BigDecimal dec(v) {
        if (v == null) return null
        if (v instanceof BigDecimal) return v
        try { return new BigDecimal(String.valueOf(v).trim()) } catch (Exception e) { return null }
    }

    /** Epoch millis from a number, a numeric string, or a bare YYYY-MM-DD (midnight UTC). */
    static Long epoch(v) {
        if (v == null) return null
        if (v instanceof Number) return ((Number) v).longValue()
        String s = String.valueOf(v).trim()
        if (s ==~ /^-?\d+$/) return Long.parseLong(s)
        if (s ==~ /^\d{4}-\d{2}-\d{2}$/) {
            return java.time.LocalDate.parse(s).atStartOfDay(java.time.ZoneOffset.UTC).toInstant().toEpochMilli()
        }
        return null
    }

    /**
     * Compare one actual against one authored string, in the subject's kind.
     * Returns an Integer (-1/0/1), or null when either side will not coerce —
     * null is "cannot answer", and the caller turns it into a reported error
     * rather than a false.
     */
    static Integer compareIn(String kind, actual, String expected) {
        if (kind == 'number') {
            BigDecimal a = dec(actual), b = dec(expected)
            return (a == null || b == null) ? null : Integer.valueOf(a.compareTo(b))
        }
        if (kind == 'date') {
            Long a = epoch(actual), b = epoch(expected)
            return (a == null || b == null) ? null : Integer.valueOf(a.compareTo(b))
        }
        if (kind == 'boolean') {
            String a = String.valueOf(actual).trim().toLowerCase()
            String b = expected.trim().toLowerCase()
            if (!(a in ['true', 'false']) || !(b in ['true', 'false'])) return null
            return Integer.valueOf(a == b ? 0 : 1)   // only == / != reach here
        }
        // string and enum: exact, case-sensitive, on purpose (see the spec)
        return Integer.valueOf(String.valueOf(actual).compareTo(expected))
    }

    /** `in` splits on commas; on a number subject the parts compare numerically. */
    static Boolean isIn(String kind, actual, String expected) {
        for (String part : expected.split(',', -1)) {
            Integer c = compareIn(kind, actual, part.trim())
            if (c == null) return null
            if (c == 0) return Boolean.TRUE
        }
        return Boolean.FALSE
    }

    /**
     * Evaluate every row and fold left. No precedence: `A Or B And C` is
     * `(A Or B) And C`, because the authoring UI has no brackets and inventing
     * precedence here would make the stored rule mean something the author never saw.
     *
     * Never throws. `error != null` means a row could not be evaluated — the
     * caller records an exception and skips the rule, and MUST NOT read the
     * false as a clean no-match.
     */
    static Map match(Map conditions, Map facts) {
        List trace = []
        List items = (conditions == null) ? null : (List) conditions.get('items')
        if (items == null || items.isEmpty()) {
            trace << 'no conditions — applies to everything'
            return [matched: true, error: null, trace: trace]
        }

        Map bag = (facts == null) ? [:] : facts
        Boolean acc = null

        for (int i = 0; i < items.size(); i++) {
            Map row = (Map) items[i]
            String subject   = row?.get('subject')
            String operator  = row?.get('operator')
            String expected  = row?.get('value') == null ? null : String.valueOf(row.get('value'))
            String connector = row?.get('connector') ?: (i == 0 ? 'If' : 'And')
            String where     = "condition ${i + 1}"

            String kind = kindOf(subject)
            if (kind == null)
                return fail(trace, "${where}: '${subject}' is not a field any rule can read")
            if (!OPERATORS.contains(operator))
                return fail(trace, "${where}: '${operator}' is not a supported operator")
            if (!operatorsFor(kind).contains(operator))
                return fail(trace, "${where}: ${operator} cannot be used on ${subject} (${kind})")
            if (expected == null || expected.trim().isEmpty())
                return fail(trace, "${where}: ${subject} ${operator} has no value to compare against")

            // A fact that is absent or null is UNKNOWN, not false. Returning false
            // here would read as "this rule does not apply", which nobody
            // investigates — and the person is quietly underpaid.
            if (!bag.containsKey(subject) || bag.get(subject) == null)
                return fail(trace, "${where}: no value supplied for '${subject}'")

            def actual = bag.get(subject)
            Boolean r

            if (operator == 'in') {
                r = isIn(kind, actual, expected)
            } else {
                Integer c = compareIn(kind, actual, expected)
                if (c == null) r = null
                else if (operator == '==') r = (c == 0)
                else if (operator == '!=') r = (c != 0)
                else if (operator == '>')  r = (c > 0)
                else if (operator == '>=') r = (c >= 0)
                else if (operator == '<')  r = (c < 0)
                else r = (c <= 0)
            }

            if (r == null)
                return fail(trace, "${where}: cannot compare ${subject} (${kind}) against '${expected}' — actual was '${actual}'")

            trace << "${connector} ${subject} ${operator} '${expected}' -> ${r} (actual '${actual}')".toString()

            if (acc == null) acc = (connector == 'Not') ? !r : r
            else if (connector == 'Or')  acc = acc || r
            else if (connector == 'Not') acc = acc && !r
            else acc = acc && r
        }

        return [matched: acc.booleanValue(), error: null, trace: trace]
    }

    private static Map fail(List trace, String message) {
        trace << ("REFUSED: " + message).toString()
        return [matched: false, error: message, trace: trace]
    }
}


// ICM | Credit Pass — name-driven
//
// Transactions in, Credit rows out. PURE: every lookup arrives already fetched and
// already indexed, so this holds no opinion about how records are read and can be
// proved against a case table.
//
// It differs from engine/CreditPass.groovy in the Sales-Commission-Management repo
// in ONE deliberate way, and the difference is the reason this file exists: that one
// enters at `transaction.positionId`, this one enters at a PAYEE NAME. The source
// export carries "Team Member: Full Name" and no position id, so a pass that demands
// a resolved seat cannot read the data the product actually receives.
//
// Two more decisions, both from the same source data:
//
//  - The SPLIT is a fact on the transaction, not only a number on the rule. The export
//    carries `Percent (%)` per row. A rule's `splitBps` OVERRIDES it; absent, the
//    source split stands; absent from both, 100%.
//  - Splits are NOT normalised to 100%. Order 00388125 credits one row at 100% and
//    another at 70%. Summing to more than 100% is overlay crediting, not corruption.
//
// Runs AFTER ConditionMatcher in the same node — it calls ConditionMatcher.match.

import java.math.BigDecimal
import java.math.RoundingMode

class CreditPass {

    static final BigDecimal BPS = new BigDecimal('10000')

    /** Effective-dated row live at an instant. Absent bound = open in that direction. */
    static boolean live(row, long asOf) {
        def s = row?.effectiveStart ?: row?.startDate ?: row?.activeStart
        def e = row?.effectiveEnd   ?: row?.endDate   ?: row?.activeEnd
        if (s != null && asOf < ((Number) s).longValue()) return false
        if (e != null && asOf > ((Number) e).longValue()) return false
        return true
    }

    /** Every dated row live at asOf. Two is not one — the caller decides if that is ambiguity. */
    static List liveRows(List rows, long asOf) {
        if (rows == null) return []
        return rows.findAll { live(it, asOf) }
    }

    static BigDecimal dec(v) { return ConditionMatcher.dec(v) }

    /** A name as a lookup key: trimmed, collapsed whitespace, lower case. */
    static String key(String s) {
        if (s == null) return null
        String t = s.trim().replaceAll(/\s+/, ' ').toLowerCase()
        return t.isEmpty() ? null : t
    }

    /**
     * Walk up the reporting line, collecting the seats to roll a credit into.
     *
     * Ends quietly on no parent, an unknown seat, or the level budget. None of those
     * is an error: a deal closed by someone reporting to nobody is a normal
     * top-of-tree deal, and failing it would fail every VP's own bookings.
     *
     * `seen` breaks a cycle rather than trusting the data not to have one.
     */
    static List ancestors(String positionId, Map parentByPosition, long asOf, int levels) {
        List out = []
        Set seen = [positionId] as Set
        String cur = positionId
        for (int i = 0; i < levels; i++) {
            List up = liveRows((List) parentByPosition[cur], asOf)
            if (up.isEmpty()) break
            String parent = up[0].parentPositionId
            if (parent == null || seen.contains(parent)) break
            out << parent
            seen << parent
            cur = parent
        }
        return out
    }

    /** `rollupLevels` as authored: '1'..'3', or 'All ancestors'. */
    static int levelsFrom(String raw) {
        if (raw == null) return 0
        String t = raw.trim()
        if (t.equalsIgnoreCase('All ancestors')) return 100
        try { return Integer.parseInt(t) } catch (Exception e) { return 0 }
    }

    /** An ObjectId-shaped record id, minted here so a parent and its children can be
     *  written in ONE batch with the FK between them already resolved. */
    static String mintId(Random rnd) {
        StringBuilder sb = new StringBuilder('e_')
        for (int i = 0; i < 24; i++) sb.append(Integer.toHexString(rnd.nextInt(16)))
        return sb.toString()
    }

    /**
     * The facts a credit rule is evaluated against. Keys are the subject paths in
     * condition-namespace.ts — this map IS the credit half of that namespace, and a
     * subject the matcher knows but this never supplies becomes a RULE_REFUSED rather
     * than a silent false.
     *
     * `position.title` carries the CODE, because that is what a rule stores.
     */
    static Map facts(Map txn, String titleCode, String territoryCode, Map payee) {
        Map f = [
            'txn.amount'         : txn.amount,
            'txn.product'        : txn.product,
            'txn.customer'       : txn.customer,
            'txn.close_date'     : txn.closeDate,
            'position.title'     : titleCode,
            'position.territory' : territoryCode,
            'payee.currency'     : payee?.currencyCode,
            'payee.hire_date'    : payee?.hireDate,
        ]
        def attrs = txn.attrs
        if (attrs instanceof Map) attrs.each { k, v -> f['txn.attrs.' + k] = v }
        return f
    }

    /** Does this plan assignment name this seat? The data carries BOTH record ids and
     *  business codes in `targetId`/`positionId`, so both are accepted — see the spec. */
    static boolean namesPosition(Map a, String posId, String posCode) {
        for (v in [a.targetId, a.positionId]) {
            if (v == null) continue
            String s = String.valueOf(v)
            if (s == posId || (posCode != null && s == posCode)) return true
        }
        return false
    }

    static boolean namesTitle(Map a, String titleId, String titleCode) {
        for (v in [a.targetId, a.titleId]) {
            if (v == null) continue
            String s = String.valueOf(v)
            if (s == titleId || (titleCode != null && s == titleCode)) return true
        }
        return false
    }

    /**
     * The pass. Never throws: an undecidable transaction lands in `exceptions` and the
     * fold continues, because one unresolvable seat must not stop a quarter.
     */
    static Map run(List transactions, Map ctx) {
        List credits = []
        List exceptions = []
        int matched = 0, rolled = 0, unmatched = 0

        Map payeeIdsByName     = ctx.payeeIdsByName     ?: [:]
        Map payeeById          = ctx.payeeById          ?: [:]
        Map seatsByPayee       = ctx.seatsByPayee       ?: [:]
        Map attrByPosition     = ctx.attrByPosition     ?: [:]
        Map parentByPosition   = ctx.parentByPosition   ?: [:]
        Map occupantByPosition = ctx.occupantByPosition ?: [:]
        Map titleCodeById      = ctx.titleCodeById      ?: [:]
        Map territoryCodeById  = ctx.territoryCodeById  ?: [:]
        Map positionCodeById   = ctx.positionCodeById   ?: [:]
        Map creditTypeIdByCode = ctx.creditTypeIdByCode ?: [:]
        Map plansById          = ctx.plansById          ?: [:]
        Map rulesByRuleId      = ctx.rulesByRuleId      ?: [:]
        List assignments       = (List) (ctx.assignments ?: [])
        Random rnd             = new Random(((Number) (ctx.seed ?: 42L)).longValue())

        def refuse = { Map t, String code, String detail ->
            exceptions << [transactionId: t.transactionId, payeeName: t.payeeName,
                           positionId: t.positionId, code: code, detail: detail]
        }

        // A plan reaches a deal only if it is Active AND in force on the date.
        def planUsable = { String planKey, long asOf ->
            Map p = (Map) plansById[planKey]
            if (p == null) return false
            if (p.status != 'Active') return false
            return live(p, asOf)
        }

        for (Map t : transactions) {
            def when = t.incentiveDate ?: t.closeDate
            if (when == null) { refuse(t, 'NO_DATE', 'neither incentiveDate nor closeDate is set'); continue }
            long asOf = ((Number) when).longValue()

            // --- name -> payee -------------------------------------------------
            String nameKey = key((String) t.payeeName)
            if (nameKey == null) { refuse(t, 'NO_PAYEE_NAME', 'the row names nobody to pay'); continue }
            List hits = (List) (payeeIdsByName[nameKey] ?: [])
            if (hits.isEmpty()) { refuse(t, 'UNRESOLVED_PAYEE', "no Payee is named '${t.payeeName}'"); continue }
            if (hits.size() > 1) { refuse(t, 'AMBIGUOUS_PAYEE', "${hits.size()} payees are named '${t.payeeName}'"); continue }
            String payeeId = (String) hits[0]
            Map payee = (Map) (payeeById[payeeId] ?: [:])

            // --- payee -> seat, as of the date ---------------------------------
            List seats = liveRows((List) seatsByPayee[payeeId], asOf)
            if (seats.isEmpty()) { refuse(t, 'NO_POSITION', "${t.payeeName} held no position on ${asOf}"); continue }
            if (seats.size() > 1) { refuse(t, 'AMBIGUOUS_POSITION', "${t.payeeName} held ${seats.size()} positions on ${asOf}"); continue }
            String pos = (String) seats[0].positionId
            String posCode = (String) positionCodeById[pos]
            t.positionId = pos

            // --- seat -> title, as of the date ---------------------------------
            List attrs = liveRows((List) attrByPosition[pos], asOf)
            String titleId   = attrs.isEmpty() ? null : (String) attrs[0].titleId
            String titleCode = titleId == null ? null : (String) titleCodeById[titleId]
            String terrCode  = attrs.isEmpty() ? null : (String) territoryCodeById[attrs[0].territoryId]

            // --- plan: the SEAT is asked first, then the TITLE ------------------
            // The seat is the more specific statement about this deal, so a plan
            // assigned to it beats one assigned to everyone carrying its title.
            // Only an ACTIVE, in-force plan wins the seat lane; an expired seat plan
            // must not shadow a title plan that is live.
            Map hit = assignments.find { a ->
                live(a, asOf) && a.targetType == 'Position' && namesPosition(a, pos, posCode) && planUsable(a.planKey, asOf)
            }
            String lane = 'Position'
            if (hit == null) {
                if (titleId == null) { refuse(t, 'NO_TITLE', "seat ${posCode ?: pos} had no title on ${asOf}"); continue }
                lane = 'Title'
                hit = assignments.find { a ->
                    live(a, asOf) && a.targetType == 'Title' && namesTitle(a, titleId, titleCode) && planUsable(a.planKey, asOf)
                }
            }
            if (hit == null) {
                refuse(t, 'NO_PLAN', "no active plan covers seat ${posCode ?: pos} or title ${titleCode ?: '(none)'} on ${asOf}")
                continue
            }

            Map plan = (Map) plansById[hit.planKey]
            Map f = facts(t, titleCode, terrCode, payee)
            boolean anyMatched = false

            for (Object rk : (List) (plan.creditRules ?: [])) {
                String ruleKey = String.valueOf(rk)
                Map rule = (Map) rulesByRuleId[ruleKey]
                if (rule == null) { refuse(t, 'RULE_MISSING', "plan ${plan.planId} points at rule ${ruleKey}, which does not exist"); continue }
                if (!live(rule, asOf)) continue          // out of force, not a failure

                Map m = ConditionMatcher.match((Map) rule.conditions, f)
                if (m.error != null) { refuse(t, 'RULE_REFUSED', "rule ${ruleKey}: ${m.error}"); continue }
                if (!m.matched) continue                  // did not apply — the normal case

                Map values = (Map) ((Map) rule.result)?.values ?: [:]

                // The rule OVERRIDES the source split; absent, the row's own split
                // stands; absent from both, the whole deal. Never a guess at 0.
                def rawSplit = values.splitBps != null ? values.splitBps : t.sourceSplitBps
                BigDecimal split = rawSplit == null ? BPS : dec(rawSplit)
                if (split == null) { refuse(t, 'BAD_SPLIT', "rule ${ruleKey} / row split is '${rawSplit}'"); continue }

                String ctCode = values.creditType == null ? null : String.valueOf(values.creditType)
                String ctId = ctCode == null ? null : (String) creditTypeIdByCode[ctCode]
                if (ctCode != null && ctId == null) {
                    refuse(t, 'UNKNOWN_CREDIT_TYPE', "rule ${ruleKey} files credits under '${ctCode}', which is not a CreditType")
                    continue
                }

                anyMatched = true
                matched++
                String creditId = mintId(rnd)
                credits << [
                    id: creditId, transactionId: t.recordId, employeeId: payeeId, positionId: pos,
                    creditRuleId: rule.recordId, creditTypeId: ctId, creditTypeCode: ctCode,
                    amount: money(dec(t.amount), split), splitBps: split.toPlainString(),
                    isRollup: false, sourceCreditId: null, hierarchyLevel: 0,
                    planId: plan.planId, ruleId: ruleKey, lane: lane,
                    payeeName: t.payeeName, orderNumber: t.orderNumber, trace: m.trace,
                ]

                if (String.valueOf(values.rollup) != 'true') continue

                def rawRoll = values.rollupSplitBps
                BigDecimal rollSplit = rawRoll == null ? split : dec(rawRoll)
                if (rollSplit == null) { refuse(t, 'BAD_SPLIT', "rule ${ruleKey} has rollupSplitBps '${rawRoll}'"); continue }
                String rollCode = values.rollupCreditType == null ? ctCode : String.valueOf(values.rollupCreditType)
                String rollId = rollCode == null ? null : (String) creditTypeIdByCode[rollCode]
                if (rollCode != null && rollId == null) {
                    refuse(t, 'UNKNOWN_CREDIT_TYPE', "rule ${ruleKey} rolls up under '${rollCode}', which is not a CreditType")
                    continue
                }

                int level = 0
                for (String up : ancestors(pos, parentByPosition, asOf, levelsFrom((String) values.rollupLevels))) {
                    level++
                    // Eligibility is NOT checked here, on purpose. A rep on leave or
                    // just terminated still generates the manager's rolled credit;
                    // whether THEY are paid is a payout-stage question.
                    List upOcc = liveRows((List) occupantByPosition[up], asOf)
                    if (upOcc.size() != 1) continue       // vacant or contested manager seat: skip quietly
                    rolled++
                    credits << [
                        id: mintId(rnd), transactionId: t.recordId, employeeId: upOcc[0].payeeId, positionId: up,
                        creditRuleId: rule.recordId, creditTypeId: rollId, creditTypeCode: rollCode,
                        amount: money(dec(t.amount), rollSplit), splitBps: rollSplit.toPlainString(),
                        isRollup: true, sourceCreditId: creditId, hierarchyLevel: level,
                        planId: plan.planId, ruleId: ruleKey, lane: lane,
                        payeeName: t.payeeName, orderNumber: t.orderNumber, trace: m.trace,
                    ]
                }
            }
            if (!anyMatched) unmatched++
        }

        return [
            credits: credits, exceptions: exceptions,
            stats: [transactions: transactions.size(), matched: matched, rolledUp: rolled,
                    unmatched: unmatched, refused: exceptions.size(), credits: credits.size()],
        ]
    }

    /**
     * amount x split, in MINOR UNITS.
     *
     * `Credit.amount` is an `integer` column, so a fraction of a paisa cannot be
     * stored and this is a rounding point. credit-pass.md says the credit pass must
     * not round — the single rounding point belongs at payout. The column is why it
     * does anyway; HALF_UP matches money-and-time.md, and the divergence is recorded
     * in the spec rather than hidden here.
     */
    static Long money(BigDecimal amount, BigDecimal splitBps) {
        if (amount == null) return null
        return amount.multiply(splitBps).divide(BPS).setScale(0, RoundingMode.HALF_UP).longValue()
    }
}


// ICM | Payout Pass — credits in, Earning and MeasureResult rows out.
//
// PURE: every lookup arrives already fetched and indexed. Runs AFTER ConditionMatcher and
// CreditPass in the same code node, and borrows CreditPass's effective-dating and
// assignment helpers (live, liveRows, namesPosition, namesTitle, mintId, dec).
//
// Two ways to calculate commission, chosen by Rule.result.values.rateType:
//
//   Flat rate  one Earning per (credit, rule):   credit.amount x rateBps / 10000
//   Tiered     one Earning per (payee, rule):    total of the payee's credits whose type is in
//              the attainment measure, divided by a quota, is the attainment; the rate
//              table tier it falls in gives the rate; total x rate is the commission.
//
// Deliberately NOT here yet: bonus, cliff, marginal tiering, percent of target, caps,
// YTD windows and true-up, eligibility hold. See docs/automations/calculate-payouts.md.
//
// Rounding happens exactly once per amount, HALF_UP, where a Long is produced. Everything
// before that is BigDecimal.

import java.math.BigDecimal
import java.math.RoundingMode

class PayoutPass {

    static final BigDecimal BPS = new BigDecimal('10000')

    static Long half(BigDecimal v) { return v == null ? null : v.setScale(0, RoundingMode.HALF_UP).longValue() }

    /**
     * A list of codes authored as a list, as "A, B", or as an OBJECT. `AttainmentMeasure.creditTypes`
     * is an untyped `object` column: an array written to it is silently stored as `{}` (probed
     * 2026-09-11), so a measure stores `{codes: [...]}`. `{items: [...]}` and `{CODE: true}` are
     * read too, because nothing else pins the shape yet.
     */
    static List codes(v) {
        List out = []
        if (v == null) return out
        if (v instanceof Map) {
            Map m = (Map) v
            def listed = m.codes != null ? m.codes : (m.items != null ? m.items : m.values)
            if (listed instanceof Collection || listed instanceof CharSequence) return codes(listed)
            for (Object k : m.keySet()) if (String.valueOf(m.get(k)) == 'true') out << String.valueOf(k)
            return out
        }
        Collection parts = (v instanceof Collection) ? (Collection) v : Arrays.asList(String.valueOf(v).split(','))
        for (Object part : parts) {
            if (part == null) continue
            String s = String.valueOf(part).trim()
            if (!s.isEmpty()) out << s
        }
        return out
    }

    /** The payout-stage half of the condition namespace: what a credit knows about itself. */
    static Map facts(Map c) {
        return [
            'credit.amount'     : c.amount,
            'credit.credit_type': c.creditTypeCode,
            'credit.close_date' : c.closeDate,
            'credit.is_rollup'  : c.isRollup ? 'true' : 'false',
            'credit.product'    : c.product,
            'credit.customer'   : c.customer,
        ]
    }

    /**
     * The credit's plan as of its date: the seat's own Active, in-force plan first, else
     * its title's. The same order Calculate Credits uses, COPIED rather than shared so the
     * credit automation's code never changes underneath it.
     */
    static Map planFor(Map c, long asOf, Map ctx) {
        Map plansById = (Map) (ctx.plansById ?: [:])
        List assignments = (List) (ctx.assignments ?: [])
        String pos = (String) c.positionId
        String posCode = (String) ((Map) (ctx.positionCodeById ?: [:]))[pos]
        def usable = { String key ->
            Map pl = (Map) plansById[key]
            return pl != null && pl.status == 'Active' && CreditPass.live(pl, asOf)
        }

        Map hit = (Map) assignments.find { Map a ->
            CreditPass.live(a, asOf) && a.targetType == 'Position' && CreditPass.namesPosition(a, pos, posCode) && usable((String) a.planKey)
        }
        String lane = 'Position'
        if (hit == null) {
            List attrs = CreditPass.liveRows((List) ((Map) (ctx.attrByPosition ?: [:]))[pos], asOf)
            String titleId = attrs.isEmpty() ? null : (String) attrs[0].titleId
            String titleCode = titleId == null ? null : (String) ((Map) (ctx.titleCodeById ?: [:]))[titleId]
            if (titleId == null) return [error: 'NO_PLAN', detail: "seat ${posCode ?: pos} had no title on ${asOf}".toString()]
            lane = 'Title'
            hit = (Map) assignments.find { Map a ->
                CreditPass.live(a, asOf) && a.targetType == 'Title' && CreditPass.namesTitle(a, titleId, titleCode) && usable((String) a.planKey)
            }
            if (hit == null) {
                return [error: 'NO_PLAN', detail: "no active plan covers seat ${posCode ?: pos} or title ${titleCode ?: titleId} on ${asOf}".toString()]
            }
        }
        return [plan: plansById[hit.planKey], lane: lane]
    }

    /** Bands must be sorted by fromPct already. Returns why they are unusable, or null. */
    static String invalidBands(List bands) {
        if (bands == null || bands.isEmpty()) return 'it has no tiers'
        for (int i = 0; i < bands.size(); i++) {
            Map b = (Map) bands[i]
            BigDecimal f = CreditPass.dec(b.fromPct), t = CreditPass.dec(b.toPct), v = CreditPass.dec(b.value)
            if (f == null || v == null) return "tier ${b.bandId} has no fromPct or value".toString()
            if (t == null && i != bands.size() - 1) return "tier ${b.bandId} has no toPct and is not the top tier".toString()
            if (t != null && f.compareTo(t) >= 0) return "tier ${b.bandId} runs from ${f} to ${t}".toString()
            if (i > 0) {
                Map prev = (Map) bands[i - 1]
                BigDecimal prevTo = CreditPass.dec(prev.toPct)
                int c = prevTo.compareTo(f)
                if (c < 0) return "gap between tier ${prev.bandId} (to ${prevTo}) and tier ${b.bandId} (from ${f})".toString()
                if (c > 0) return "tier ${prev.bandId} (to ${prevTo}) overlaps tier ${b.bandId} (from ${f})".toString()
            }
        }
        return null
    }

    /** fromPct inclusive, toPct exclusive; above the top tier stays in the top tier; below the lowest is null. */
    static Map tierFor(List bands, BigDecimal attainment) {
        if (attainment.compareTo(CreditPass.dec(((Map) bands[0]).fromPct)) < 0) return null
        for (Object o : bands) {
            Map b = (Map) o
            BigDecimal f = CreditPass.dec(b.fromPct), t = CreditPass.dec(b.toPct)
            if (attainment.compareTo(f) >= 0 && (t == null || attainment.compareTo(t) < 0)) return b
        }
        return (Map) bands[bands.size() - 1]
    }

    static Map run(List credits, Map ctx) {
        List earnings = []
        List measureResults = []
        List exceptions = []
        int flat = 0, tiered = 0
        Random rnd = new Random(((Number) (ctx.seed ?: 42L)).longValue())
        String periodId = (String) ctx.periodId
        long periodEnd = ((Number) ctx.periodEnd).longValue()
        Map rulesByRuleId = (Map) (ctx.rulesByRuleId ?: [:])
        Map groups = new TreeMap()

        def refuse = { Map c, String ruleKey, String code, String detail ->
            exceptions << [creditId: c?.creditId ?: '', employeeId: c?.employeeId ?: '', ruleId: ruleKey ?: '',
                           code: code, detail: detail]
        }

        List ordered = new ArrayList(credits)
        ordered.sort { a, b -> String.valueOf(a.creditId) <=> String.valueOf(b.creditId) }

        for (Map c : ordered) {
            if (c.asOf == null) { refuse(c, null, 'NO_DATE', "credit ${c.creditId}: its transaction has no incentive or close date".toString()); continue }
            if (c.amount == null) { refuse(c, null, 'NO_AMOUNT', "credit ${c.creditId} has no amount".toString()); continue }
            if (c.creditTypeCode == null) { refuse(c, null, 'UNKNOWN_CREDIT_TYPE', "credit ${c.creditId} has a credit type no CreditType row carries".toString()); continue }
            long asOf = ((Number) c.asOf).longValue()

            Map pf = planFor(c, asOf, ctx)
            if (pf.error != null) { refuse(c, null, (String) pf.error, (String) pf.detail); continue }
            Map plan = (Map) pf.plan
            Map f = facts(c)

            for (Object rk : codes(plan.payoutRules)) {
                String ruleKey = String.valueOf(rk)
                Map rule = (Map) rulesByRuleId[ruleKey]
                if (rule == null) { refuse(c, ruleKey, 'RULE_MISSING', "plan ${plan.planId} lists payout rule ${ruleKey}, which does not exist".toString()); continue }
                if (!CreditPass.live(rule, asOf)) continue      // out of force on the credit's date

                Map values = (Map) (((Map) rule.result)?.values ?: [:])
                String rateType = values.rateType == null ? '' : String.valueOf(values.rateType).trim()
                if (!(rateType in ['Flat rate', 'Tiered'])) {
                    refuse(c, ruleKey, 'UNSUPPORTED_RATE_TYPE', "rule ${ruleKey}: rateType '${rateType}' is neither Flat rate nor Tiered".toString())
                    continue
                }
                String payWhen = values.payWhen == null ? '' : String.valueOf(values.payWhen).trim()
                if (!payWhen.isEmpty() && payWhen != 'On close') {
                    refuse(c, ruleKey, 'UNSUPPORTED_PAY_WHEN', "rule ${ruleKey}: payWhen '${payWhen}' is not supported yet - only On close".toString())
                    continue
                }

                Map m = ConditionMatcher.match((Map) rule.conditions, f)
                if (m.error != null) { refuse(c, ruleKey, 'RULE_REFUSED', "rule ${ruleKey}: ${m.error}".toString()); continue }
                if (!m.matched) continue

                if (rateType == 'Flat rate') {
                    List types = codes(values.creditTypes)
                    if (!types.isEmpty() && !types.contains(c.creditTypeCode)) continue
                    BigDecimal rate = CreditPass.dec(values.rateBps)
                    if (rate == null) { refuse(c, ruleKey, 'RULE_REFUSED', "rule ${ruleKey}: rateBps '${values.rateBps}' is not a number".toString()); continue }
                    BigDecimal base = (BigDecimal) c.amount
                    Long amount = half(base.multiply(rate).divide(BPS))
                    flat++
                    earnings << [
                        earningId: CreditPass.mintId(rnd), rateType: rateType, componentKey: ruleKey, planId: plan.planId,
                        employeeId: c.employeeId, positionId: c.positionId, creditId: c.creditId, resultId: '',
                        transactionId: c.transactionId, orderNumber: c.orderNumber ?: '', creditType: c.creditTypeCode,
                        base: half(base), rateApplied: half(rate), bandHit: '', attainmentPct: 0L,
                        amount: amount, earnedToDate: amount, previouslyPaid: 0L,
                        holdStatus: 'Payable', periodId: periodId,
                        trace: [lane: pf.lane, conditions: m.trace],
                    ]
                } else {
                    String gk = c.employeeId + '|' + ruleKey
                    Map g = (Map) groups[gk]
                    if (g == null) {
                        g = [employeeId: c.employeeId, ruleKey: ruleKey, values: values, planId: plan.planId, lane: pf.lane, credits: []]
                        groups[gk] = g
                    }
                    ((List) g.credits) << c
                }
            }
        }

        // --- tiered: one decision per (payee, rule) -----------------------------------
        for (Object o : groups.values()) {
            Map g = (Map) o
            Map values = (Map) g.values
            String ruleKey = (String) g.ruleKey
            def refuseGroup = { String code, String detail ->
                exceptions << [creditId: '', employeeId: g.employeeId, ruleId: ruleKey, code: code, detail: detail]
            }

            String measureKey = values.measureId == null ? '' : String.valueOf(values.measureId).trim()
            Map measure = (Map) ((Map) (ctx.measuresByKey ?: [:]))[measureKey]
            if (measure == null) { refuseGroup('NO_MEASURE', "rule ${ruleKey}: attainment measure '${measureKey}' does not exist".toString()); continue }

            // A measure may name its credit types by code or by CreditType record id.
            Set measureTypes = new LinkedHashSet()
            for (Object t : codes(measure.creditTypes)) {
                measureTypes << String.valueOf(((Map) (ctx.creditTypeCodeById ?: [:]))[t] ?: t)
            }
            List included = ((List) g.credits).findAll { Map c -> measureTypes.contains(c.creditTypeCode) }
            BigDecimal total = BigDecimal.ZERO
            for (Object ic : included) total = total.add((BigDecimal) ((Map) ic).amount)

            List seatSource = included.isEmpty() ? (List) g.credits : included
            Map latest = (Map) seatSource.max { Map c -> ((Number) c.asOf).longValue() }
            String seat = (String) latest.positionId

            // --- quota: the rule's own, else the payee's -----------------------------------
            List quotas = (List) (ctx.quotas ?: [])
            Map quota = null
            String quotaKey = values.quotaId == null ? '' : String.valueOf(values.quotaId).trim()
            if (!quotaKey.isEmpty()) {
                List hits = quotas.findAll { Map q -> q.quotaId == quotaKey }
                if (hits.isEmpty()) { refuseGroup('NO_QUOTA', "rule ${ruleKey}: quota '${quotaKey}' does not exist".toString()); continue }
                quota = (Map) hits[0]
            } else {
                List candidates = quotas.findAll { Map q ->
                    q.positionId == seat && (q.measureId == measure.recordId || q.measureId == measure.measureId) && CreditPass.live(q, periodEnd)
                }
                List hits = []
                for (Object pid : (List) (ctx.coverPeriodIds ?: [periodId])) {
                    hits = candidates.findAll { Map q -> q.periodId == pid }
                    if (!hits.isEmpty()) break
                }
                if (hits.isEmpty()) {
                    refuseGroup('NO_QUOTA', "no quota on seat ${seat} for measure ${measure.measureId} covering ${ctx.periodName}".toString())
                    continue
                }
                if (hits.size() > 1) {
                    refuseGroup('AMBIGUOUS_QUOTA', "${hits.size()} quotas on seat ${seat} for measure ${measure.measureId} on the same period".toString())
                    continue
                }
                quota = (Map) hits[0]
            }
            BigDecimal quotaAmount = CreditPass.dec(quota.amount)
            if (quotaAmount == null || quotaAmount.signum() <= 0) {
                refuseGroup('NO_QUOTA', "quota ${quota.quotaId} has amount '${quota.amount}'".toString())
                continue
            }

            // --- rate table tier ------------------------------------------------------------
            String rtKey = values.rateTableId == null ? '' : String.valueOf(values.rateTableId).trim()
            Map rt = (Map) ((Map) (ctx.rateTablesByKey ?: [:]))[rtKey]
            if (rt == null || !CreditPass.live(rt, periodEnd)) {
                refuseGroup('NO_RATE_TABLE', "rule ${ruleKey}: rate table '${rtKey}' does not exist or is not in force".toString())
                continue
            }
            List bands = (List) rt.bands
            String bad = invalidBands(bands)
            if (bad != null) { refuseGroup('RATE_TABLE_INVALID', "rate table ${rtKey}: ${bad}".toString()); continue }

            BigDecimal attainment = total.multiply(BPS).divide(quotaAmount, 10, RoundingMode.HALF_UP)
            Map tier = tierFor(bands, attainment)
            if (tier == null) {
                refuseGroup('NO_TIER', "attainment ${attainment.setScale(2, RoundingMode.HALF_UP)} bps is below the lowest tier of ${rtKey}".toString())
                continue
            }
            BigDecimal rate = CreditPass.dec(tier.value)
            Long amount = half(total.multiply(rate).divide(BPS))

            String resultId = CreditPass.mintId(rnd)
            measureResults << [
                resultId: resultId, employeeId: g.employeeId, positionId: seat, measureId: measure.recordId,
                measureKey: measure.measureId, periodId: periodId, componentKey: ruleKey,
                creditTotal: half(total), quota: half(quotaAmount), attainmentPct: half(attainment),
            ]
            tiered++
            earnings << [
                earningId: CreditPass.mintId(rnd), rateType: 'Tiered', componentKey: ruleKey, planId: g.planId,
                employeeId: g.employeeId, positionId: seat, creditId: '', resultId: resultId,
                transactionId: '', orderNumber: '', creditType: measureTypes.join(','),
                base: half(total), rateApplied: half(rate), bandHit: String.valueOf(tier.label ?: tier.bandId),
                attainmentPct: half(attainment),
                amount: amount, earnedToDate: amount, previouslyPaid: 0L,
                holdStatus: 'Payable', periodId: periodId,
                trace: [lane: g.lane, measure: measure.measureId, quota: quota.quotaId, quotaPeriodId: quota.periodId,
                        rateTable: rtKey, tier: tier.bandId, credits: included.size()],
            ]
        }

        long sum = 0L
        for (Object e : earnings) sum += ((Number) ((Map) e).amount).longValue()
        return [
            earnings: earnings, measureResults: measureResults, exceptions: exceptions,
            stats: [credits: credits.size(), flatEarnings: flat, tieredEarnings: tiered,
                    measureResults: measureResults.size(), refused: exceptions.size(), total: sum],
        ]
    }
}


// --- wiring: platform rows in, PayoutPass out ------------------------------------
//
// Everything above this line is PURE. Below is the adapter: it indexes what the fetch
// nodes returned into the maps PayoutPass expects, and shapes what it returns into
// something that survives the response boundary (Longs and Strings, no BigDecimal).

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }
def truthy(v) { return v instanceof Boolean ? v : String.valueOf(v) == 'true' }

// The tiered reads sit behind a branch lane that stays closed when no tiered rule applies.
// A pill to a node that never ran leaves the binding MISSING, so every fetch input is read
// through here.
def opt = { String n -> binding.hasVariable(n) ? binding.getVariable(n) : null }
def R = { String n -> rows(opt(n + 'Rows')) }

def group(List src, String byField, Closure shape) {
    Map out = [:]
    for (r in src) {
        def k = p(r, byField)
        if (k == null) continue
        out.computeIfAbsent(String.valueOf(k), { [] }) << shape(r)
    }
    return out
}

// --- a page that did not hold everything is a WRONG answer, not a slow one --------
List truncated = []
def bound = { String label, String param -> if (truthy(opt(param + 'More'))) truncated << label }
bound('Credit', 'credit'); bound('Transaction', 'txn'); bound('CreditType', 'ct')
bound('PositionAttribute', 'attr'); bound('Position', 'pos'); bound('Title', 'title')
bound('PlanAssignment', 'asg'); bound('Plan', 'plan'); bound('Rule', 'rule')
bound('AttainmentMeasure', 'measure'); bound('RateTable', 'rt'); bound('RateTableBand', 'band')
bound('Quota', 'quota'); bound('Period (cover)', 'cover')

String creditRunKeyOut = opt('creditRunKey') == null ? '' : String.valueOf(opt('creditRunKey'))
def refuseRun = { String status, String message ->
    return [status: status, message: message, runId: runId, dryRun: truthy(dryRun), periodName: periodName,
            creditRunId: creditRunKeyOut, written: 0, earnings: [], measureResults: [], exceptions: [],
            stats: [:], expectedEarnings: 0, expectedResults: 0]
}
if (!truncated.isEmpty()) {
    return refuseRun('FETCH_TRUNCATED',
        ("these objects returned more rows than one page held, so any answer would be computed on a prefix: "
         + truncated.join(', ') + ". Raise pageLimit.").toString())
}
if (truthy(opt('creditOverflow'))) {
    return refuseRun('KEY_SET_TOO_LARGE',
        "this credit run touches more distinct transactions or seats than keyCap allows; calculate it in chunks".toString())
}

// --- reference codes -------------------------------------------------------------
Map creditTypeCodeById = [:]
for (t in R('ct')) { def c = p(t, 'creditTypeCode'); if (c != null) creditTypeCodeById[t.id] = String.valueOf(c) }
Map titleCodeById = [:]
for (t in R('title')) titleCodeById[t.id] = p(t, 'titleCode')
Map positionCodeById = [:]
for (t in R('pos')) positionCodeById[t.id] = p(t, 'positionCode')
Map txnById = [:]
for (t in R('txn')) txnById[t.id] = t

// --- plans and payout rules --------------------------------------------------------
Map plansById = [:]
for (pl in R('plan')) {
    Map v = [planId: p(pl, 'planId'), status: p(pl, 'status'), startDate: p(pl, 'startDate'),
             endDate: p(pl, 'endDate'), payoutRules: p(pl, 'payoutRules') ?: []]
    plansById[pl.id] = v
    if (v.planId != null) plansById[String.valueOf(v.planId)] = v
}
Map rulesByRuleId = [:]
for (r in R('rule')) {
    def rk = p(r, 'ruleId')
    if (rk == null || p(r, 'stage') != 'payout') continue
    rulesByRuleId[String.valueOf(rk)] = [recordId: r.id, ruleId: rk, conditions: p(r, 'conditions'),
                                         result: p(r, 'result'), activeStart: p(r, 'activeStart'), activeEnd: p(r, 'activeEnd')]
}
List assignments = R('asg').collect {
    [planKey: p(it, 'planId'), targetType: p(it, 'targetType'), targetId: p(it, 'targetId'),
     titleId: p(it, 'titleId'), positionId: p(it, 'positionId'), startDate: p(it, 'startDate'), endDate: p(it, 'endDate')]
}

// --- tiered config -------------------------------------------------------------------
Map measuresByKey = [:]
for (m in R('measure')) {
    def k = p(m, 'measureId'); if (k == null) continue
    measuresByKey[String.valueOf(k)] = [recordId: m.id, measureId: String.valueOf(k), creditTypes: p(m, 'creditTypes'),
                                        periodType: p(m, 'periodType')]
}
Map bandsByTable = group(R('band'), 'rateTableId', {
    [bandId: p(it, 'bandId'), fromPct: p(it, 'fromPct'), toPct: p(it, 'toPct'), value: p(it, 'value'), label: p(it, 'label')]
})
Map rateTablesByKey = [:]
for (t in R('rt')) {
    def k = p(t, 'rateTableId'); if (k == null) continue
    List bands = new ArrayList((List) (bandsByTable[t.id] ?: []))
    bands.sort { a, b ->
        BigDecimal x = CreditPass.dec(a.fromPct), y = CreditPass.dec(b.fromPct)
        if (x == null) return 1
        if (y == null) return -1
        return x <=> y
    }
    rateTablesByKey[String.valueOf(k)] = [recordId: t.id, rateTableId: String.valueOf(k), bands: bands,
                                          effectiveStart: p(t, 'effectiveStart'), effectiveEnd: p(t, 'effectiveEnd')]
}
List quotas = R('quota').collect {
    [recordId: it.id, quotaId: p(it, 'quotaId'), positionId: p(it, 'positionId'), measureId: p(it, 'measureId'),
     periodId: p(it, 'periodId'), amount: p(it, 'amount'), effectiveStart: p(it, 'effectiveStart'), effectiveEnd: p(it, 'effectiveEnd')]
}
// This period first, then the periods that contain it, narrowest first: a quota on the month
// beats one on the quarter, which beats one on the year.
String thisPeriod = String.valueOf(periodId)
List coverRows = R('cover').findAll { String.valueOf(it.id) != thisPeriod }
coverRows.sort { a, b ->
    long sa = ((Number) (p(a, 'endDate') ?: 0)).longValue() - ((Number) (p(a, 'startDate') ?: 0)).longValue()
    long sb = ((Number) (p(b, 'endDate') ?: 0)).longValue() - ((Number) (p(b, 'startDate') ?: 0)).longValue()
    return sa <=> sb
}
List coverPeriodIds = [thisPeriod] + coverRows.collect { String.valueOf(it.id) }

// --- the credits -------------------------------------------------------------------
List credits = []
for (cr in R('credit')) {
    def txn = txnById[p(cr, 'transactionId')]
    Map attrs = (p(txn, 'attrs') instanceof Map) ? (Map) p(txn, 'attrs') : [:]
    def when = p(txn, 'incentiveDate') ?: p(txn, 'closeDate')
    credits << [
        recordId      : cr.id,
        creditId      : p(cr, 'creditId') ?: cr.id,
        employeeId    : p(cr, 'employeeId'),
        positionId    : p(cr, 'positionId'),
        transactionId : p(cr, 'transactionId'),
        creditTypeCode: creditTypeCodeById[p(cr, 'creditTypeId')],
        amount        : CreditPass.dec(p(cr, 'amount')),
        isRollup      : p(cr, 'sourceCreditId') != null,
        asOf          : when instanceof Number ? ((Number) when).longValue() : null,
        closeDate     : p(txn, 'closeDate'),
        product       : p(txn, 'product'),
        customer      : p(txn, 'customer'),
        orderNumber   : attrs.orderNumber ?: p(txn, 'sourceId'),
    ]
}

Map ctx = [
    seed: ((Number) startedAt).longValue(), periodId: thisPeriod, periodName: periodName,
    periodEnd: ((Number) windowEnd).longValue(),
    attrByPosition: group(R('attr'), 'positionId', { [titleId: p(it, 'titleId'),
                                                     effectiveStart: p(it, 'effectiveStart'), effectiveEnd: p(it, 'effectiveEnd')] }),
    titleCodeById: titleCodeById, positionCodeById: positionCodeById, creditTypeCodeById: creditTypeCodeById,
    plansById: plansById, rulesByRuleId: rulesByRuleId, assignments: assignments,
    measuresByKey: measuresByKey, rateTablesByKey: rateTablesByKey, quotas: quotas, coverPeriodIds: coverPeriodIds,
]

Map out = PayoutPass.run(credits, ctx)

// SORTED so two runs of the same period diff cleanly and suite indexes mean something.
List earnings = new ArrayList((List) out.earnings)
earnings.sort { a, b ->
    int c = String.valueOf(a.componentKey) <=> String.valueOf(b.componentKey); if (c != 0) return c
    c = String.valueOf(a.employeeId) <=> String.valueOf(b.employeeId); if (c != 0) return c
    return String.valueOf(a.creditId) <=> String.valueOf(b.creditId)
}
List measureResults = new ArrayList((List) out.measureResults)
measureResults.sort { a, b ->
    int c = String.valueOf(a.componentKey) <=> String.valueOf(b.componentKey); if (c != 0) return c
    return String.valueOf(a.employeeId) <=> String.valueOf(b.employeeId)
}
List exceptions = new ArrayList((List) out.exceptions)
exceptions.sort { a, b ->
    int c = String.valueOf(a.code) <=> String.valueOf(b.code); if (c != 0) return c
    c = String.valueOf(a.ruleId) <=> String.valueOf(b.ruleId); if (c != 0) return c
    c = String.valueOf(a.employeeId) <=> String.valueOf(b.employeeId); if (c != 0) return c
    return String.valueOf(a.creditId) <=> String.valueOf(b.creditId)
}

Map stats = new LinkedHashMap((Map) out.stats)
stats.put('rowsRead', [credits: R('credit').size(), transactions: R('txn').size(), attributes: R('attr').size(),
                       positions: R('pos').size(), planAssignments: assignments.size(), plans: R('plan').size(),
                       rules: R('rule').size(), measures: R('measure').size(), rateTables: R('rt').size(),
                       tiers: R('band').size(), quotas: quotas.size()])

return [status: 'OK', message: '', runId: runId, dryRun: truthy(dryRun), periodName: periodName,
        creditRunId: creditRunKeyOut, written: 0, earnings: earnings, measureResults: measureResults,
        exceptions: exceptions, stats: stats, expectedEarnings: earnings.size(), expectedResults: measureResults.size()]

// Turn the computed measure results and earnings into rows bulk_upsert_records_by_id stores.
//
// The CalculationRun RECORD id is stamped here because it does not exist until n_CrRun ran,
// and rows go out as {id, updateFields:[...]} - a flat row answers success with a zero count
// and writes nothing. Ids were minted in the fold, so an Earning already carries the id of
// the MeasureResult it came from.

def rows(v) { return (v instanceof List) ? v : [] }
def blank = { v -> v == null || String.valueOf(v).trim().isEmpty() }

String run = runId == null ? '' : String.valueOf(runId).trim()
String period = periodId == null ? '' : String.valueOf(periodId).trim()

def fieldsOf = { Map values ->
    List fields = []
    values.each { k, v -> if (!blank(v)) fields << [fieldName: 'properties.' + k, actionType: 'SET', setValue: v] }
    return fields
}

List mr = []
for (Map m : rows(measureResults)) {
    mr << [id: m.resultId, updateFields: fieldsOf([
        resultId: m.resultId, runId: run, employeeId: m.employeeId, positionId: m.positionId,
        measureId: m.measureId, periodId: period, creditTotal: m.creditTotal, quota: m.quota,
        attainmentPct: m.attainmentPct,
    ])]
}

List er = []
for (Map e : rows(earnings)) {
    er << [id: e.earningId, updateFields: fieldsOf([
        earningId: e.earningId, runId: run, employeeId: e.employeeId, componentKey: e.componentKey,
        periodId: period, creditId: e.creditId, resultId: e.resultId,
        earnedToDate: e.earnedToDate, previouslyPaid: e.previouslyPaid, amount: e.amount,
        rateApplied: e.rateApplied, bandHit: e.bandHit, holdStatus: e.holdStatus ?: 'Payable',
        payablePeriodId: period, trace: e.trace,
    ])]
}

return [mrUpdates: mr, earnUpdates: er, mrExpected: mr.size(), earnExpected: er.size()]

// Close the payout run, and supersede the period's previous payout runs only if this one
// fully landed.
//
// `bulk_upsert_records_by_id` answers `success:false, successCount:0` for an EMPTY batch
// (uacode StorageBulkUpsertAction) - a flat-only period has no measure results - so the
// counts, not the success flag, decide. A run that lands short is Failed and supersedes
// nothing, so readers keep the last good run.

def opt = { String n -> binding.hasVariable(n) ? binding.getVariable(n) : null }
def num = { v -> v instanceof Number ? ((Number) v).longValue() : 0L }
def rows(v) { return (v instanceof List) ? v : [] }

String run = String.valueOf(runRecordId)
long mrLand = num(opt('mrLanded')), mrMeant = num(opt('mrExpected'))
long erLand = num(opt('earnLanded')), erMeant = num(opt('earnExpected'))
boolean ok = mrLand == mrMeant && erLand == erMeant

List updates = [[id: run, updateFields: [
    [fieldName: 'properties.status', actionType: 'SET', setValue: ok ? 'Succeeded' : 'Failed'],
]]]
if (ok) {
    for (id in rows(opt('supersede'))) {
        String s = String.valueOf(id)
        if (s == '__none__' || s == run) continue
        updates << [id: s, updateFields: [
            [fieldName: 'properties.status', actionType: 'SET', setValue: 'Superseded'],
            [fieldName: 'properties.supersededBy', actionType: 'SET', setValue: run],
        ]]
    }
}

return [
    ok     : ok,
    landed : erLand,
    updates: updates,
    message: ok ? '' : "meant to write ${mrMeant} measure results and ${erMeant} earnings; ${mrLand} and ${erLand} landed".toString(),
]
